```openscad
// T-shaped extrusion nut - rides in the slot of an aluminium extrusion
// Print orientation: bottom flange on the bed (z = 0), neck pointing up.
// The profile is centred on the origin in X and Y.

// ---------------- Parameters ----------------
profile_len   = 10;    // length of the T along X (mm)
flange_w      = 12;    // width of the bottom flange along Y (mm)
flange_t      = 2.5;   // thickness of the flange (mm), z = 0 .. 2.5
neck_w        = 6;     // width of the neck above the flange (mm)
neck_top_z    = 5.5;   // height the neck reaches (mm)
screw_d       = 3.4;   // diameter of the vertical screw hole (mm)
eps           = 0.5;   // cutter overshoot past faces (mm)
$fn           = 64;    // curve resolution

// Derived
total_h = neck_top_z;  // 5.5 mm overall height
x0      = -profile_len / 2;  // -5.0
y0      = -flange_w / 2;     // -6.0

// ---------------- Model ----------------
difference() {
    union() {
        // Bottom flange: rectangle in XY, extruded from z = 0 to z = flange_t
        translate([x0, y0, 0])
            cube([profile_len, flange_w, flange_t]);

        // Neck: centred on the origin, rising from the top of the flange
        translate([x0, 0, flange_t])
            cube([profile_len, neck_w, neck_top_z - flange_t]);
    }

    // Vertical screw hole through the full height (with overshoot)
    translate([0, 0, -eps])
        cylinder(d = screw_d, h = total_h + 2 * eps);
}
