```openscad
// Flat dial ring with radial tick marks for a rotary stage
// Print orientation: flat on bed, top face (with grooves) facing up

// ---------- Parameters ----------
outer_d      = 70;    // ring outer diameter
inner_d      = 50;    // ring inner diameter
thickness    = 5;     // ring thickness (Z)
tick_count   = 36;    // number of tick marks
tick_w       = 1.5;   // tick width (radial)
tick_depth   = 1.5;   // tick depth from top face
tick_length  = 4;     // tick inward length from outer edge
eps          = 0.5;   // cutter overshoot past faces

$fn = 128;

// ---------- Model ----------
difference() {
    // Ring body
    cylinder(d = outer_d, h = thickness);

    // Central bore
    translate([0, 0, -eps])
        cylinder(d = inner_d, h = thickness + 2 * eps);

    // Radial tick grooves, first on +X axis
    for (i = [0 : tick_count - 1])
        rotate([0, 0, i * 360 / tick_count])
            translate([outer_d / 2 - tick_length, 0, thickness - tick_depth])
                cube([tick_w, thickness + eps, tick_depth + eps]);
}
