// Flat dial ring with radial tick marks for a rotary stage
// Print orientation: flat on bed, top face (with grooves) facing up

// ---------- Parameters ----------
outer_d      = 50;    // ring outer diameter
inner_d      = 34;    // ring inner diameter
thickness    = 3;     // ring thickness (Z)
tick_count   = 12;    // number of radial tick marks
tick_w       = 1.5;   // tick width (groove width)
tick_depth   = 1.5;   // tick depth (groove depth from top face)
tick_len     = 3;     // tick length (inward from outer edge)
cut_extra    = 0.5;   // overshoot of cutters past faces
$fn          = 96;    // curve resolution

// ---------- Derived ----------
tick_start_angle = 0;   // first tick on +X axis

// ---------- Model ----------
difference() {
    // Ring body
    cylinder(d = outer_d, h = thickness);

    // Central bore
    translate([0, 0, -cut_extra])
        cylinder(d = inner_d, h = thickness + 2 * cut_extra);

    // Radial tick grooves
    for (i = [0 : tick_count - 1]) {
        a = tick_start_angle + i * 360 / tick_count;
        translate([outer_d / 2 - tick_len * cos(a),
                   0,
                   thickness - tick_depth])
            rotate([0, 90, a])
                linear_extrude(height = tick_w)
                    circle(d = tick_len * 2, $fn = 64);
    }
}
