handle_h = rim_z - handle_t;  // handle bottom Z (z = 9)

// ---------------- Model ----------------
union() {
    // Hollow spherical bowl: lower half of shell, bottom at z = 0
    difference() {
        translate([0, 0, bowl_r])
            sphere(r = bowl_r);
        translate([0, 0, wall])
            sphere(r = bowl_r - wall + eps);
        // keep only lower half (y < 0), discard upper hemisphere
        translate([0, -eps, 0])
            cube([bowl_r + eps, 2 * eps, bowl_r + eps]);
    }

    // Flat handle, top face flush with rim (z = 12..15)
    translate([handle_x0, -handle_w / 2, handle_h])
        cube([handle_x1 - handle_x0, handle_w, handle_t]);
