        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckle cylinders, axis along X at y = 12.5
        for (i = [0 : knuckle_n - 1]) {
            // 1st, 3rd, 5th segments -> i = 0, 2, 4
            if (i % 2 == 0)
                translate([(i - (knuckle_n - 1)/2) * knuckle_pitch,
                           plate_wid/2 - eps,
                           knuckle_z])
                    cylinder(d = knuckle_d, h = plate_wid*2 + 2*eps);
