    // Pin holes along the knuckle axis through every knuckle
    for (i = [0 : knuckle_n - 1]) {
        if (i % 2 == 0)
            translate([(i - (knuckle_n - 1)/2) * knuckle_pitch,
                       plate_wid/2 - eps,
                       knuckle_z])
                cylinder(d = pin_d, h = plate_wid*2 + 2*eps);
