// Leaf of a pin hinge
// Print orientation: flat plate on the bed, knuckles pointing up (+Z)

// ---------- Parameters ----------
plate_length   = 50;    // plate length along X (mm)
plate_width    = 25;    // plate width along Y (mm)
plate_thick    = 2.5;   // plate thickness along Z (mm)

knuckle_count  = 5;     // number of segments (and knuckles) along the +Y edge
knuckle_dia    = 7;     // diameter of each round knuckle (mm)
knuckle_z      = 3.5;   // height of knuckle top above plate (mm)

pin_dia        = 3;     // diameter of the pin hole through each knuckle (mm)

eps            = 0.5;   // overshoot for clean boolean cuts (mm)
$fn            = 96;    // curve resolution

// ---------- Derived ----------
segment_len = plate_length / knuckle_count;   // 10 mm per segment
knuckle_x   = [i * segment_len for i in [0 : knuckle_count - 1]]; // X positions of knuckles

// ---------- Model ----------
difference() {
    union() {
        // Base plate, centred in X and Y, resting on z = 0
        translate([-plate_length / 2, -plate_width / 2, 0])
            cube([plate_length, plate_width, plate_thick]);

        // Knuckles along the +Y edge (y = plate_width / 2 = 12.5)
        for (x in knuckle_x)
            translate([x, plate_width / 2, 0])
                cylinder(d = knuckle_dia, h = knuckle_z, $fn = $fn);
    }

    // Pin holes running along the X axis through every knuckle
    for (x in knuckle_x)
        translate([x, plate_width / 2, -eps])
            rotate([0, 90, 0])
                cylinder(d = pin_dia, h = knuckle_dia + 2 * eps, $fn = $fn);
}
