// Eccentric cam for a shaker mechanism
// Print orientation: disc flat on the bed, hub rising in +Z

// ---------------- Parameters ----------------
disc_d      = 50;    // cam disc diameter
disc_h      = 8;     // cam disc thickness
offset_x    = 5;     // disc centre X offset from shaft axis
offset_y    = 0;     // disc centre Y offset from shaft axis

hub_d       = 14;    // shaft hub diameter
hub_top_z   = 5;     // hub height above disc (hub spans z = 8 to 13)

shaft_d     = 6;     // shaft through-hole diameter

eps         = 0.5;   // cutter overshoot past faces
$fn         = 128;   // curve resolution

// ---------------- Model ----------------
union() {
    // Cam disc, centred at (offset_x, offset_y, 0)
    translate([offset_x, offset_y, 0])
        cylinder(d = disc_d, h = disc_h);

    // Shaft hub, centred on the Z axis, from z = disc_h to z = disc_h + hub_top_z
    translate([0, 0, disc_h])
        cylinder(d = hub_d, h = hub_top_z);

    // Shaft through-hole on the Z axis, extending past both faces
    translate([0, 0, -eps])
        cylinder(d = shaft_d, h = disc_h + hub_top_z + 2 * eps);
}
