// ---------------- Parameters ----------------
disc_d      = 30;    // disc diameter
disc_h      = 8;     // disc thickness
hub_d       = 11;    // hub diameter
hub_rise    = 6;     // hub height above the disc (z = 8 to 14)
shaft_d     = 5;     // shaft hole diameter
offset_x    = 5;     // disc centre X offset from the shaft axis
offset_y    = 0;     // disc centre Y offset from the shaft axis
eps         = 0.5;   // cutter overshoot past faces

$fn = 96;

// ---------------- Model ----------------
difference() {
    union() {
        // Eccentric disc
        translate([offset_x, offset_y, 0])
            cylinder(d = disc_d, h = disc_h);

        // Hub that rises around the shaft axis (z = 8 to 14)
        translate([0, 0, disc_h - hub_rise])
            cylinder(d = hub_d, h = hub_rise + 0.01);
    }

    // Shaft hole: through the hub and through the disc on the Z axis
    translate([0, 0, -eps])
        cylinder(d = shaft_d, h = disc_h + hub_rise + 2 * eps);
}
