```openscad
// Star-shaped indexing wheel
// Print orientation: flat on bed, z = 0 up to plate thickness

// ---------------- Parameters ----------------
plate_thickness   = 5;     // plate thickness (Z)
outer_radius      = 30;    // distance of outer points from centre
inner_radius      = 15;    // distance of inner points from centre
hole_radius       = 3;     // central through-hole radius (6 mm diameter)
point_count       = 8;     // number of points (outer and inner)
cut_extra         = 0.5;   // overshoot for clean boolean cuts
$fn               = 96;    // curve resolution

// ---------------- Model ----------------
difference() {
    // 8-pointed star outline, first outer point on +X axis
    star_outline = concat(
        [for (i = [0 : point_count - 1])
            [outer_radius * cos((i * 2 * pi) / point_count),
             outer_radius * sin((i * 2 * pi) / point_count)]],
        [for (i = [0 : point_count - 1])
            [inner_radius * cos(((i + 0.5) * 2 * pi) / point_count),
             inner_radius * sin(((i + 0.5) * 2 * pi) / point_count)]]
    );

    union() {
        // Star plate with central hole
        difference() {
            linear_extrude(height = plate_thickness)
                polygon(points = star_outline);
            translate([0, 0, -cut_extra])
                cylinder(r = hole_radius, h = plate_thickness + 2 * cut_extra);
        }
    }
}
```

