// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 upward

// ---- Dimensions (mm) ----
thickness      = 3;    // specimen thickness (Z)
total_length   = 110;  // overall length along X
gauge_width    = 8;    // gauge section width (Y)
gauge_length   = 30;   // gauge section length (X)
grip_width     = 15;   // grip section width (Y)
grip_length    = 30;   // grip section length (X)
transition_len = 10;   // transition section length (X)

// Derived
eps       = 0.5;   // cutter overshoot past faces
$fn       = 64;    // curve resolution (no curves here, set per rule)

// Check: 2*grip + 2*transition + gauge = 2*15 + 2*10 + 30 = 80 mm
// The user's numbers do not add to the stated total_length (110 mm).
// Following the explicit instruction to model each section as given,
// the rendered part will be 80 mm long. Extend the cutters by eps
// so no faces are coplanar.

difference() {
    union() {
        // Left grip
        translate([-total_length/2 + grip_length, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);

        // Gauge section (centred on origin)
        translate([-gauge_length/2, -gauge_width/2, 0])
            cube([gauge_length, gauge_width, thickness]);

        // Right grip
        translate([total_length/2 - grip_length, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);
    }

    // Transition: width changes linearly from grip_width to gauge_width
    // Overlap the end of each transition into its neighbouring section
    // by eps, keeping the stated transition length.
    for (s = [-1, 1]) {   // s = -1 left, +1 right
        x0 = s > 0 ? total_length/2 - grip_length - eps
                   : -total_length/2 + grip_length + eps;
        w0 = grip_width;
        x1 = x0 + s * transition_len;
        w1 = gauge_width;
        translate([x0, -w0/2, 0])
            cube([transition_len + eps, w0, thickness]);
        translate([x1 - eps, -w1/2, 0])
            cube([transition_len + eps, w1, thickness]);
    }
}
