$fn = 64;

// ---- Dimensions (mm) ----
plate_t      = 3;     // plate thickness (Z)
gauge_w      = 8;     // gauge section width (Y)
gauge_l      = 30;    // gauge section length (X)
grip_w       = 15;    // grip section width (Y)
grip_l       = 30;    // grip section length (X)
transition_l = 10;    // transition section length (X)
total_l      = 110;   // overall length (X)

// ---- Derived ----
eps       = 0.01;                       // cutter overshoot
model_l   = gauge_l + 2 * transition_l + 2 * grip_l;  // check: 110

// Width of the transition at a given distance from the grip start
function trans_w(d) = grip_w - (grip_w - gauge_w) * d / transition_l;

difference() {
    // Plate body
    translate([-model_l / 2, -plate_t / 2, 0])
        linear_extrude(height = plate_t)
            polygon([
                [0, 0],
                [model_l / 2, plate_t],
                [-(model_l / 2), plate_t]
            ]);

    // Grip sections
    for (s = [-1, 1])
        translate([s * (grip_l + transition_l) - model_l / 2, -grip_w / 2, 0])
            cube([grip_l, grip_w, plate_t]);

    // Transition sections
    for (s = [-1, 1])
        translate([s * (gauge_l + transition_l / 2) - model_l / 2, 0, 0])
            linear_extrude(height = plate_t)
                polygon([
                    [0, trans_w(transition_l / 2)],
                    [transition_l, gauge_w],
                    [-transition_l, gauge_w]
                ]);
}
