        translate([-total_length/2, -grip_width/2, 0])
            rectangle([grip_length, grip_width]);
        // Right grip
        translate([total_length/2 - grip_length, -grip_width/2, 0])
            rectangle([grip_length, grip_width]);
        // Gauge section
        translate([-total_length/2 + grip_length + transition_length,
                   -gauge_width/2, 0])
            rectangle([gauge_length, gauge_width]);
        // Transitions (width changes linearly from grip to gauge)
        for (s = [-1, 1]) {
            x0 = -total_length/2 + (1 - s)/2 * transition_length;
            w0 = grip_width + s * (gauge_width - grip_width);
            x1 = x0 + s * transition_length;
            w1 = grip_width + s * (gauge_width - grip_width);
            translate([x0, -w0/2, 0])
                linear_extrude(height = thickness)
                    polygon([[0, 0], [transition_length, 0],
                             [transition_length, w0], [0, w0]]);
        }
    }
