            cube([grip_length, grip_width, thickness]);

        // Gauge section (centered)
        translate([-total_length / 2 + grip_length + transition_len,
                   -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, thickness]);

        // Left transition: width goes from grip_width down to gauge_width
        translate([-total_length / 2 + grip_length, -grip_width / 2, 0])
            linear_extrude(thickness)
                polygon(points = [
                    [0, -grip_width / 2],
                    [transition_len, -gauge_width / 2],
                    [transition_len, gauge_width / 2],
                    [0, gauge_width / 2]
                ]);

        // Right transition: width goes from gauge_width up to grip_width
        translate([total_length / 2 - grip_length - transition_len,
                   -gauge_width / 2, 0])
            linear_extrude(thickness)
                polygon(points = [
                    [0, -gauge_width / 2],
                    [transition_len, -grip_width / 2],
                    [transition_len, grip_width / 2],
                    [0, gauge_width / 2]
                ]);
    }

    // Deburring cuts past each face
    translate([-total_length / 2 - cut_extra, 0, -cut_extra])
        cube([total_length + 2 * cut_extra, 100, 2 * cut_extra]);
}
