    union() {
        // Outer rim
        cylinder(d = outer_diameter, h = part_thickness);

        // Hub
        translate([0, 0, -cut_extra])
            cylinder(d = hub_diameter, h = part_thickness + 2 * cut_extra);

        // Spokes, evenly spaced, first along +X
        for (i = [0 : spoke_count - 1]) {
            rotate([0, 0, spoke_start_angle + i * 360 / spoke_count])
                translate([0, -spoke_width / 2, 0])
                    cube([spoke_reach, spoke_width, part_thickness]);
