neck_w        = 7;     // width of the neck above the flange
neck_top_z    = 6;     // height the neck reaches (z = 6)
screw_d       = 4.5;   // diameter of the vertical screw hole
eps           = 0.5;   // cutter overshoot past faces

// Derived
neck_h = neck_top_z - flange_t;   // neck height between flange and top (3 mm)

// ---------------- Model ----------------
difference() {
    union() {
        // Bottom flange: rectangle in XY, extruded from z = 0 to z = flange_t
        translate([-profile_len / 2, -flange_w / 2, 0])
            cube([profile_len, flange_w, flange_t]);

        // Neck: centred on the origin, running from z = flange_t to z = neck_top_z
        translate([0, 0, flange_t])
            cube([profile_len, neck_w, neck_h]);
    }

    // Vertical screw hole through the full height (z = 0 to z = neck_top_z)
    translate([0, 0, -eps])
        cylinder(d = screw_d, h = flange_t + neck_h + 2 * eps);
}
