// Ring weight for a water bath, sitting around the neck of a flask.
// Print orientation: flat on the bed, torus axis along Z.

// ---------------- Parameters ----------------
cross_d      = 12;    // diameter of the round cross-section (mm)
ring_r       = 35;    // radius of the circle the cross-section centre traces (mm)
ring_h       = 6;     // height of the cross-section, so the middle plane is at z = 6 (mm)
cut_extra    = 0.5;   // overshoot of the cutting shape past the faces (mm)
$fn          = 96;    // resolution for curved surfaces

// Derived
ring_d       = ring_r * 2 + cross_d;   // overall across diameter (82 mm)
cross_r      = cross_d / 2;            // cross-section radius

