    // Torus body, centred on z = 6, resting on z = 0
    translate([0, 0, ring_h - cross_r])
        cylinder(r = cross_r, h = ring_d, $fn = $fn);

    // Central hole along Z, extending past top and bottom faces
    translate([0, 0, -cut_extra])
        cylinder(r = ring_r + cut_extra, h = ring_d + 2 * cut_extra, $fn = $fn);
}
