// Leaf of a pin hinge
// Print orientation: flat on bed, knuckles pointing up (+Z)

// ---------- Parameters ----------
plate_length   = 50;    // plate length along X (mm)
plate_width    = 20;    // plate width along Y (mm)
plate_thick    = 3;     // plate thickness along Z (mm)

knuckle_count  = 5;     // number of segments (and knuckles)
knuckle_dia    = 6;     // knuckle cylinder diameter (mm)
knuckle_h      = 0.5;   // knuckle height above plate top (mm)
knuckle_x      = 10;    // spacing between knuckle axes (mm)
knuckle_y      = 10;    // knuckle axis Y position (mm)
pin_dia        = 3;     // pin hole diameter (mm)

eps            = 0.5;   // cutter overshoot past faces (mm)
$fn            = 96;    // curve resolution

// ---------- Derived ----------
segment_len = plate_length / knuckle_count;   // 10 mm

// ---------- Model ----------
difference() {
    union() {
        // Base plate, centred in X/Y, resting on z = 0
        translate([-plate_length/2, -plate_width/2, 0])
            cube([plate_length, plate_width, plate_thick]);

        // Knuckles on the +Y edge (1st, 3rd, 5th segments)
        for (i = [0 : knuckle_count - 1]) {
            if ((i + 1) % 2 == 0) continue;   // skip even segments
            translate([(i + 0.5) * knuckle_x, knuckle_y, plate_thick - knuckle_h])
                cylinder(d = knuckle_dia, h = knuckle_h + eps);
        }
    }

    // Pin holes running along X through every knuckle
    for (i = [0 : knuckle_count - 1]) {
        if ((i + 1) % 2 == 0) continue;
        translate([(i + 0.5) * knuckle_x - pin_dia/2,
                   knuckle_y,
                   plate_thick - knuckle_h - eps])
            rotate([0, 90, 0])
                cylinder(d = pin_dia, h = knuckle_h + 2 * eps);
    }
}
