// Eccentric cam for a shaker mechanism
// Print orientation: disc flat on the bed, hub rising in +Z

// ---------------- Parameters ----------------
disc_d      = 30;    // cam disc diameter
disc_h      = 6;     // cam disc thickness
disc_x      = 5;     // disc centre offset in X (sits 5 mm off the shaft)
disc_y      = 0;     // disc centre offset in Y

hub_d       = 11;    // shaft hub diameter
hub_h       = 4;     // hub height above the disc (z = 6 to 10)

shaft_d     = 5;     // shaft hole diameter (through both hub and disc)

eps         = 0.5;   // cutter overshoot past faces
$fn         = 96;    // curve resolution

// ---------------- Model ----------------
union() {
    // Cam disc, centred at (disc_x, disc_y, disc_h)
    translate([disc_x, disc_y, 0])
        cylinder(d = disc_d, h = disc_h);

    // Shaft hub, centred on the Z axis, rising from z = disc_h to z = disc_h + hub_h
    translate([0, 0, disc_h])
        cylinder(d = hub_d, h = hub_h);
}

// Shaft hole: starts above the disc top face and ends above the hub top face
// (extends through both disc and hub on the shaft axis)
