eps       = 0.5;  // cutter overshoot past faces

$fn = 96;

// ---- Model ----
difference() {
    // Star outline, first outer point on +X axis
    hull() {
        for (i = [0 : points - 1])
            rotate([0, 0, i * 360 / points])
                translate([outer_r, 0, 0])
                    cylinder(h = plate_t, $fn = 6);
    }

    // Central through-hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = plate_t + 2 * eps, $fn = 6);
}
