// Flat dial ring with radial tick marks for a rotary stage
// Print orientation: flat on bed, top face (with grooves) facing up

// ---------- Parameters ----------
outer_d      = 50;    // ring outer diameter
inner_d      = 34;    // ring inner diameter
thickness    = 5;     // ring thickness (Z)
tick_count   = 12;    // number of radial tick marks
tick_w       = 1.5;   // tick width
tick_depth   = 1;     // tick depth from top face
tick_length  = 4;     // tick inward length from outer edge
cut_extra    = 0.5;   // overshoot of cutters past faces
$fn          = 96;    // curve resolution

// ---------- Derived ----------
tick_r_start = outer_d / 2 - tick_length;   // outer end of ticks
tick_r_end   = outer_d / 2 + cut_extra;     // cutter extends past outer edge

// ---------- Model ----------
difference() {
    // Ring body
    cylinder(d = outer_d, h = thickness);

    // Central bore
    translate([0, 0, -cut_extra])
        cylinder(d = inner_d, h = thickness + 2 * cut_extra);

    // Radial tick grooves, first on +X axis
    for (i = [0 : tick_count - 1])
        rotate([0, 0, i * 360 / tick_count])
            translate([0, -tick_w / 2, 0])
                linear_extrude(height = tick_depth)
                    polygon([
                        [tick_r_start, 0],
                        [tick_r_end,   tick_w / 2],
                        [tick_r_end,  -tick_w / 2]
                    ]);
}
