plate_len    = 80;    // plate length along X (mm)
plate_wid    = 50;    // plate width along Y (mm)
plate_thk    = 2;     // plate thickness (mm), z = 0..2

rib_thk      = 2;     // rib thickness along X (mm)
rib_h        = 4;     // rib height above plate (mm), z = 2..6
rib_count    = 3;     // number of ribs
rib_pitch    = 20;    // centre-to-centre spacing of ribs (mm)
rib_x0       = 20;    // centre X of first rib (mm)

eps          = 0.5;   // overlap for clean boolean unions (mm)
$fn          = 64;    // curve resolution (no curves here, set per convention)

// Derived
plate_top_z  = plate_thk;
rib_top_z    = plate_top_z + rib_h;
outer_off    = rib_pitch;   // outer ribs are this far from plate ends

// ---------------- Model ----------------
union() {
    // Base plate, centred in X and Y
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs running full width along Y, overlapping into plate for a solid union
    for (i = [0 : rib_count - 1]) {
        translate([rib_x0 + i * rib_pitch - rib_thk/2,
                   -plate_wid/2 - eps,
                   plate_top_z])
            cube([rib_thk, plate_wid + 2*eps, rib_h]);
    }
}
