plate_wid   = 50;   // plate width along Y (mm)
plate_thk   = 2;    // plate thickness (mm), z = 0..2

rib_h       = 4;    // rib height above plate (mm), z = 2..6
rib_thk     = 2;    // rib thickness along X (mm)
rib_count   = 3;    // number of ribs
rib_pitch   = 20;   // centre-to-centre spacing of ribs (mm)

eps         = 0.5;  // overlap for clean booleans (mm)
$fn         = 64;   // curve resolution (no curves here, set per convention)

// ---------- Derived ----------
// Ribs run the full width, centred on the plate
plate_z0 = 0;
plate_z1 = plate_thk;
rib_z0   = plate_z1 - eps;  // ribs start inside the plate for a solid union
rib_z1   = plate_z0 + plate_thk + rib_h;  // top of ribs at z = 6

// ---------- Model ----------
union() {
    // Base plate
    translate([-plate_len/2, -plate_wid/2, plate_z0])
        cube([plate_len, plate_wid, plate_z1]);

    // Ribs, centred 20 mm apart, outer ones 20 mm from the ends
    for (i = [0 : rib_count - 1]) {
        x_c = (i < 1 || i > rib_count - 2) ?
               (i == 0 ? -plate_len/2 + rib_pitch :
                i == rib_count - 1 ? plate_len/2 - rib_pitch) :
               (i - (rib_count - 1)/2) * rib_pitch;
        translate([x_c - rib_thk/2, -plate_wid/2, rib_z0])
            cube([rib_thk, plate_wid, rib_z1]);
    }
}
