// ---------- Parameters ----------
plate_len   = 80;   // plate length along X (mm)
plate_wid   = 80;   // plate width along Y (mm)
plate_thk   = 3;    // plate thickness (mm), z = 0..3

rib_thk     = 2;    // rib thickness along X (mm)
rib_h       = 6;    // rib height above plate (mm), z = 3..9
rib_count   = 3;    // number of ribs
rib_pitch   = 20;   // centre-to-centre spacing of ribs (mm)

eps         = 0.5;  // overlap of ribs into plate for a clean union (mm)
$fn         = 64;   // curve resolution (no curves here, set per convention)

// ---------- Derived ----------
// Ribs run the full width, centred on the plate
plate_x0 = -plate_len/2;   // plate starts at x = -40
plate_xL = plate_len;      // plate ends at x = 40

// ---------- Model ----------
union() {
    // Base plate
    translate([plate_x0, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs, centred 20 mm apart, outer ones 20 mm from the ends
    for (i = [0 : rib_count - 1]) {
        x_c = plate_x0 + plate_len/2 - (rib_count + 1)/2 * rib_pitch + i * rib_pitch;
        translate([x_c - rib_thk/2, -plate_wid/2, plate_thk - eps])
            cube([rib_thk, plate_wid, rib_h + eps]);
    }
}
