bowl_r      = 15;    // outer radius of spherical bowl (mm)
wall        = 1.5;   // bowl wall thickness (mm)
handle_w    = 12;    // handle width along Y (mm)
handle_t    = 4;     // handle thickness along Z (mm)
handle_x0   = 13.5;  // handle start position along X (mm)
handle_x1   = 75;    // handle end position along X (mm)
eps         = 0.5;   // cutter overshoot past faces (mm)

// ---- Derived ----
inner_r = bowl_r - wall;   // inner radius of bowl
handle_z0 = bowl_r - handle_t;  // handle bottom Z (flush with rim top)

// ---- Model ----
union() {
    // Bowl: lower half of hollow sphere, centred at (0, 0, bowl_r)
    difference() {
        translate([0, 0, 0])
            sphere(r = bowl_r, $fn = 96);
        translate([0, 0, wall])
            sphere(r = inner_r, $fn = 96);
    }

    // Flat handle along +X
    translate([handle_x0, -handle_w / 2, handle_z0])
        cube([handle_x1 - handle_x0, handle_w, handle_t]);
}
