// Ring weight for a water bath, sitting around the neck of a flask.
// Print orientation: flat on the bed, torus axis along Z.

// ---------------- Parameters ----------------
cross_d      = 16;    // diameter of the round cross-section (mm)
ring_r       = 28;    // radius of the circle the cross-section centre traces (mm)
ring_h       = 8;     // height of the cross-section, so the middle plane is at z = 8 (mm)
cut_extra    = 0.5;   // overshoot of the cutting shape past the faces (mm)
$fn          = 128;   // facet count for round features

// Derived
ring_d = 2 * ring_r;   // overall ring diameter (72 mm)

// ---------------- Model ----------------
difference() {
    // Torus body: cylinder of radius cross_d/2 swept around Z
    translate([0, 0, cut_extra])
        cylinder(r = cross_d / 2, h = ring_h + 2 * cut_extra, $fn = $fn);

    // Central hole: a cylinder whose axis lies on the ring (radius 28),
    // running through the full height, so no faces are coplanar
    translate([0, 0, cut_extra])
        rotate([0, 90, 0])
            cylinder(r = ring_r, h = ring_h + 2 * cut_extra, $fn = $fn);
}
