    // Base plate
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Knuckles on 1st, 3rd, 5th segments
    for (i = [0 : 2 : 4]) {
        translate([first_x + i*knuckle_x - knuckle_d/2,
                   plate_wid/2,
                   plate_thk])
            cylinder(d = knuckle_d, h = knuckle_h, $fn = 96);
