```openscad
// Leaf of a pin hinge
// Print orientation: flat on bed, knuckles pointing up (+Z)

// ---------- Parameters ----------
plate_length   = 60;    // plate length along X (mm)
plate_width    = 25;    // plate width along Y (mm)
plate_thick    = 3;     // plate thickness along Z (mm)

knuckle_count  = 5;     // number of knuckle segments
knuckle_pitch  = 12;    // segment length (mm)
knuckle_d      = 7;     // knuckle cylinder diameter (mm)
knuckle_z      = 3.5;   // knuckle axis height above plate (mm)

pin_d          = 3;     // pin hole diameter (mm)

eps            = 0.5;   // cutter overshoot past faces (mm)
$fn            = 96;    // curve resolution

// ---------- Derived ----------
knuckle_r = knuckle_d / 2;
// 1st segment starts at x = -plate_length/2, then step by pitch
// 1st, 3rd, 5th segments -> indices 0, 2, 4
knuckle_x0 = -plate_length / 2;

// ---------- Model ----------
union() {
    // Base plate
    translate([-plate_length / 2, -plate_width / 2, 0])
        cube([plate_length, plate_width, plate_thick]);

    for (i = [0 : 2 : knuckle_count - 1]) {
        translate([knuckle_x0 + i * knuckle_pitch - knuckle_r,
                   plate_width / 2,
                   knuckle_z])
            difference() {
                cylinder(r = knuckle_r, h = plate_thick + 2 * eps);
                // Pin hole through the knuckle along X
                translate([knuckle_x0 + i * knuckle_pitch - knuckle_r - eps,
                           plate_width / 2,
                           knuckle_z])
                    rotate([0, 90, 0])
                        cylinder(d = pin_d, h = knuckle_d + 2 * eps);
            }
    }
}
