hub_h         = hub_top_z - 5;  // hub height (6 mm)

shaft_d       = 6;     // shaft hole diameter

eps           = 0.5;   // cutter overshoot past faces
$fn           = 128;   // curve resolution

// ---------- Model ----------
difference() {
    union() {
        // Eccentric disc
        translate([disc_x, disc_y, 0])
            cylinder(d = disc_d, h = disc_h);

        // Hub around the shaft axis
        translate([0, 0, 5])
            cylinder(d = hub_d, h = hub_h);
    }

    // Shaft hole through hub and disc
    translate([0, 0, -eps])
        cylinder(d = shaft_d, h = disc_h + hub_h + 2 * eps);
}
