    // Tapered frustum body
    translate([-block_bottom_w / 2, -block_bottom_h / 2, 0])
        linear_extrude(height = block_top_z, center = true)
            polygon([
                [-block_bottom_w / 2, -block_bottom_w / 2],
                [ block_bottom_w / 2, -block_bottom_w / 2],
                [ block_bottom_w / 2,  block_bottom_w / 2],
                [-block_bottom_w / 2,  block_bottom_w / 2]
            ]);

    // Pocket cut into the top face (extends past the top to avoid coplanar faces)
    translate([-block_pocket_w / 2, -block_pocket_w / 2, block_top_z - block_pocket_d])
        cube([block_pocket_w, block_pocket_w, block_pocket_d + eps]);
