$fn = 64;

// ---- Dimensions (mm) ----
thickness      = 3;     // plate thickness (Z)
total_length   = 120;   // overall length along X
gauge_width    = 10;    // narrow gauge section width (Y)
gauge_length   = 40;    // gauge section length (X)
grip_width     = 19;    // grip section width (Y)
grip_length    = 25;    // grip section length (X)
transition_len = 15;    // length of each grip-gauge transition

// ---- Derived ----
transition_start = -(total_length / 2 + grip_length);  // left end of left transition
transition_end   = (total_length / 2 - grip_length);   // right end of right transition

// ---- Model ----
difference() {
    union() {
        // Grip sections
        translate([-(total_length / 2), -grip_width / 2, 0])
            cube([grip_length, grip_width, thickness]);
        translate([total_length / 2 - grip_length, -grip_width / 2, 0])
            cube([grip_length, grip_width, thickness]);

        // Gauge section
        translate([0, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, thickness]);

        // Transitions (width changes linearly from grip to gauge)
        for (s = [-1, 1]) {
            translate([s * transition_start, 0, 0])
                rotate([0, 90, 0])
                    linear_extrude(height = thickness)
                        polygon(points = [
                            [0, (grip_width + gauge_width) / 2],
                            [transition_len, gauge_width / 2]
                        ]);
        }
    }
}
