difference() {
    union() {
        // End grip sections
        translate([-total_len / 2 + grip_len, -half_grip, 0])
            cube([grip_len, grip_w, plate_t]);
        translate([ total_len / 2 - grip_len, -half_grip, 0])
            cube([grip_len, grip_w, plate_t]);

        // Central gauge section
        translate([-total_len / 2 + grip_len + transition_w, -gauge_w / 2, 0])
            cube([gauge_len, gauge_w, plate_t]);
    }

    // Transition zones: width changes linearly from grip_w to gauge_w
    for (s = [-1, 1]) {
        x0 = -total_len / 2 + grip_len;          // start of transition
        x1 = x0 + transition_w;                   // end of transition
        translate([s * (x1 - x0) / 2, 0, 0])
            linear_extrude(height = plate_t)
                polygon(points = [
                    [x0, -grip_w / 2],
                    [x1, -gauge_w / 2],
                    [x1,  gauge_w / 2],
                    [x0,  grip_w / 2]
                ]);
    }
}
