                    [grip_length, grip_width/2],
                    [0, grip_width/2]
                ]);

    // Gauge section (inner)
    translate([-gauge_length/2, -gauge_width/2, 0])
        linear_extrude(thickness + 2*cut_overlap)
            polygon([
                [0, -gauge_width/2],
                [gauge_length, -gauge_width/2],
                [gauge_length, gauge_width/2],
