// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 up to z = thickness

// ---------------- Parameters ----------------
thickness      = 3;     // specimen thickness (Z)
gauge_width    = 6;     // narrow gauge width (Y)
gauge_length   = 30;    // gauge section length (X)
grip_width     = 20;    // grip section width (Y)
grip_length    = 25;    // grip section length (X)
transition_len = 15;    // length of each transition region (X)
eps            = 0.5;   // cutter overshoot past faces

$fn = 64;

// Derived: overall length and half-widths
total_length = grip_length + transition_len + gauge_length + transition_len + grip_length;
half_grip    = grip_width / 2;
half_gauge   = gauge_width / 2;

// ---------------- Model ----------------
difference() {
    // Solid body: outline extruded through thickness
    translate([-total_length / 2, -half_grip, 0])
        hull() {
            // End grips
            translate([-total_length / 2, -half_grip, 0])
                cube([grip_length, grip_width, thickness]);
            translate([total_length / 2 - grip_length, -half_grip, 0])
                cube([grip_length, grip_width, thickness]);

            // Gauge section
            translate([-total_length / 2 + grip_length + transition_len, -half_gauge, 0])
                cube([gauge_length, gauge_width, thickness]);

            // Transitions (hull interpolates linearly between widths)
        }

    // Deburr / clean up: cut slightly into each flat face
    translate([-total_length / 2 - eps, -half_grip - eps, 0])
        cube([total_length / 2 + eps, grip_width + 2 * eps, thickness + 2 * eps]);
    translate([total_length / 2 + eps, -half_grip - eps, 0])
        cube([total_length / 2 + eps, grip_width + 2 * eps, thickness + 2 * eps]);
}
