        cylinder(d = outer_diameter, h = part_thickness);

        // Hub
        translate([0, 0, rim_id - cut_extra])
            cylinder(d = hub_diameter, h = part_thickness + 2 * cut_extra);

        // Spokes
        for (i = [0 : spoke_count - 1]) {
            a = spoke_start_ang + i * 360 / spoke_count;
            translate([hub_diameter / 2, 0, 0])
                rotate([0, 0, a])
                    linear_extrude(height = part_thickness)
                        polygon([[-hub_diameter / 2 - cut_extra, -spoke_width / 2],
                                 [-hub_diameter / 2 - cut_extra, spoke_width / 2],
                                 [ rim_width / 2 + cut_extra,  spoke_width / 2],
                                 [ rim_width / 2 + cut_extra, -spoke_width / 2]]);
        }
    }

    // Axle hole through hub
    translate([0, 0, -cut_extra])
        cylinder(d = axle_hole_d, h = part_thickness + 2 * cut_extra);
}
