// Stiffened cover panel: flat plate with 3 longitudinal ribs
// Print orientation: plate flat on bed, ribs pointing up (+Z)

// ---------------- Parameters ----------------
plate_len    = 80;    // plate length along X (mm)
plate_wid    = 80;    // plate width along Y (mm)
plate_thk    = 2;     // plate thickness (mm), z = 0..2

rib_thk      = 2;     // rib thickness along X (mm)
rib_h        = 6;     // rib height above plate (mm), z = 2..8
rib_count    = 3;     // number of ribs
rib_pitch    = 20;    // centre-to-centre spacing of ribs (mm)
rib_x_offset = 20;    // distance of outer ribs from plate ends (mm)

eps          = 0.5;   // overlap for clean boolean unions (mm)
$fn          = 64;    // curve resolution (no curves here, set per convention)

// ---------------- Derived ----------------
rib_x1 = [0, rib_pitch, 2 * rib_pitch];   // rib centre X positions (0, 20, 40)
// outer ribs are 20 mm from the ends, which puts their centres at 20 and 60

// ---------------- Model ----------------
union() {
    // Base plate, centred in X and Y, resting on z = 0
    translate([-plate_len / 2, -plate_wid / 2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs running the full width along Y
    for (x = rib_x1) {
        translate([x - rib_thk / 2, -plate_wid / 2 - eps, plate_thk])
            cube([rib_thk, plate_wid + 2 * eps, rib_h]);
    }
}
