handle_x0  = bowl_radius + overlap;     // 10.5 mm: handle start (inside bowl)
handle_x1  = handle_length;             // 110 mm: handle end

// ---------------- Model ----------------
union() {
    // Hollow spherical bowl: lower half only, rim at z = 10
    difference() {
        translate([0, 0, 0])
            sphere(r = bowl_radius);
        translate([0, 0, bowl_wall])
            sphere(r = bowl_inner);
    }

    // Flat handle, top face flush with rim (z = 10)
    translate([handle_x0, -handle_width / 2, bowl_wall])
        cube([handle_x1 - handle_x0, handle_width, handle_thick]);
}
