ring_r       = 20;   // radius of the ring's centre circle
ring_w       = 52;   // overall width of the ring (2 * ring_r)
ring_z       = 6;    // height of the ring (middle plane at z = 6)
eps          = 0.5;  // cutter overshoot past faces

// Derived
cross_r = cross_d / 2;

// Torus: circle of radius cross_r swept around Z axis at radius ring_r
module ring_weight() {
    difference() {
        translate([0, 0, ring_z - eps])
            linear_extrude(height = cross_d + 2 * eps)
                circle(r = ring_r, $fn = 96);
        translate([0, 0, ring_z - cross_d - 2 * eps])
            rotate([0, 90, 0])
                cylinder(r = cross_r, h = ring_w + 4 * eps, $fn = 96);
    }
}

ring_weight();
