// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 upward

// ---- Dimensions (mm) ----
thickness      = 4;    // specimen thickness (Z)
total_length  = 140;   // overall length along X
gauge_width   = 6;     // narrow gauge section width (Y)
gauge_length  = 50;    // gauge section length (X)
grip_width    = 19;    // grip section width (Y)
grip_length   = 35;    // grip section length (X)
transition_length = 10; // transition region length between grip and gauge

// ---- Derived ----
transition_start = -total_length/2 + grip_length;   // -62.5
transition_end   = transition_start + transition_length; // -52.5

// ---- Model ----
difference() {
    union() {
        // Grip sections
        translate([-total_length/2, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);
        translate([total_length/2 - grip_length, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);

        // Gauge section
        translate([-gauge_length/2, -gauge_width/2, 0])
            cube([gauge_length, gauge_width, thickness]);

        // Transition regions (linear width change)
        for (s = [-1, 1]) {
            translate([s * (total_length/2 - grip_length - transition_length/2), 0, 0])
                linear_extrude(thickness)
                    polygon([
                        [0, -grip_width/2],
                        [transition_length/2, -grip_width/2 + (gauge_width - grip_width)/2/transition_length],
                        [transition_length/2, (gauge_width - grip_width)/2/transition_length],
                        [transition_length, (gauge_width - grip_width)/2/transition_length]
                    ]);
        }
    }
}
