grip_len     = 35;    // grip section length (X)
transition_w = 10;    // transition section length (X)

// ---- Derived ----
eps       = 0.01;                                           // cutter overshoot
transition = total_len - 2 * grip_len - gauge_len;          // check: 2*10 = 20

// ---- Model ----
difference() {
    // Solid body
    translate([-total_len / 2, -plate_t / 2, 0])
        linear_extrude(height = plate_t)
            polygon([
                [-total_len / 2, -grip_w / 2],
                [ total_len / 2, -grip_w / 2],
                [ total_len / 2,  grip_w / 2],
                [-total_len / 2,  grip_w / 2]
            ]);

    // Cut out gauge and transitions
    for (sx = [-1, 1]) {
        x0 = sx < 0 ? -grip_len - transition : total_len / 2 - grip_len - transition;
        x1 = sx < 0 ? transition - 1 : total_len / 2 - transition + 1;
        translate([x0, -grip_w / 2 - eps, 0])
            linear_extrude(height = plate_t + 2 * eps)
                polygon([
                    [x1, -grip_w / 2 - eps],
                    [x1,  grip_w / 2 + eps],
                    [-total_len / 2,  grip_w / 2 + eps],
                    [-total_len / 2, -grip_w / 2 - eps]
                ]);
    }
