// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 upward

// ---- Dimensions (mm) ----
thickness      = 4;    // specimen thickness (Z)
total_length   = 150;  // overall length along X
gauge_width    = 6;    // narrow gauge section width (Y)
gauge_length   = 50;   // gauge section length (X)
grip_width     = 15;   // grip section width (Y)
grip_length    = 35;   // grip section length (X)
transition_len = 15;   // length of each grip-to-gauge transition

// ---- Derived ----
eps   = 0.5;           // cutter overshoot past faces
$fn   = 64;

// Check: 2*grip_length + gauge_length + 2*transition_len = 150
assert(abs(2*grip_length + gauge_length + 2*transition_len - total_length) < 0.001, "length mismatch");

// Width of the transition at a given distance from the grip start
function trans_w(d) = grip_width + (gauge_width - grip_width) * d / transition_len;

difference() {
    // Main body
    translate([-total_length/2, -thickness/2, 0])
        linear_extrude(thickness)
            hull() {
                // Left grip
                translate([-total_length/2, -grip_width/2, 0])
                    rectangle([grip_length, grip_width]);
                // Right grip
                translate([total_length/2 - grip_length, -grip_width/2, 0])
                    rectangle([grip_length, grip_width]);
                // Gauge
                translate([-total_length/2 + grip_length + transition_len, -gauge_width/2, 0])
                    rectangle([gauge_length, gauge_width]);
            }
    // Cut the two transition regions so the gauge is exactly gauge_width wide
    for (s = [-1, 1])
        translate([s * (total_length/2 - grip_length - transition_len/2), 0, -eps])
            rotate([0, 90, 0])
                linear_extrude(height = transition_len)
                    polygon(points = [
                        [0, trans_w(transition_len/2)],
                        [transition_len, gauge_width]
                    ]);
}
