// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 up to plate_t

$fn = 64;

// ---- Dimensions (mm) ----
plate_t      = 4;     // plate thickness (Z)
total_len    = 150;   // overall length along X
gauge_w      = 8;     // gauge section width (Y)
gauge_len    = 50;    // gauge section length (X)
grip_w       = 20;    // grip section width (Y)
grip_len     = 35;    // grip section length (X)
transition_w = 15;    // transition section length (X)

// ---- Derived ----
eps       = 0.01;                                           // cutter overshoot
transition = total_len - 2 * grip_len - gauge_len;          // check: 15

// Width at the start of each transition (same as grip width)
function tw(start_w, end_w, len) = start_w + (end_w - start_w) * eps / len;

difference() {
    // Main plate
    translate([-total_len / 2, -plate_t / 2, 0])
        cube([total_len, plate_t, plate_t]);

    // Grip sections
    for (sx = [-1, 1])
        translate([sx > 0 ? total_len / 2 - grip_len : -total_len / 2, -plate_t / 2, 0])
            cube([grip_len, grip_w, plate_t]);

    // Transition sections
    for (sx = [-1, 1])
        translate([sx > 0 ? total_len / 2 - grip_len - transition : -total_len / 2 - transition, -plate_t / 2, 0])
            cube([transition, tw(grip_w, gauge_w, transition), plate_t]);

    // Gauge section
    translate([-total_len / 2 + gauge_len / 2, -plate_t / 2, 0])
        cube([gauge_len, gauge_w, plate_t]);
}
