// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 up to plate_t

$fn = 64;

// ---- Dimensions (mm) ----
plate_t      = 3;     // plate thickness (Z)
total_len    = 120;   // overall length along X
grip_w       = 19;    // grip section width (Y)
grip_len     = 30;    // grip section length along X
gauge_w      = 10;    // gauge section width (Y)
gauge_len    = 30;    // gauge section length along X
transition_w = 15;    // transition section length along X

// ---- Derived ----
eps       = 0.01;                    // cutter overshoot past faces
half_grip = grip_w / 2;              // 9.5 mm
half_gauge = gauge_w / 2;            // 5 mm

// Check: grip + gauge + 2*transition = 120 mm
assert(abs(grip_len + gauge_len + 2 * transition_w - total_len) < 0.001,
       "Dimensions do not add up to total_len");

// ---- Model ----
difference() {
    // Solid plate
    translate([-total_len / 2, -plate_t / 2, 0])
        cube([total_len, plate_t, plate_t]);

    // Cut out the groove: grip -> transition -> gauge -> transition -> grip
    // Width of the groove at position x (carried through Z)
    function groove_w(x) =
        abs(x) <= grip_len       ? grip_w :
        abs(x) <= grip_len + transition_w ?
            gauge_w + (grip_w - gauge_w) *
                (abs(x) - grip_len) / transition_w :
        abs(x) > total_len - grip_len - transition_w ?
            gauge_w + (grip_w - gauge_w) *
                (total_len - grip_len - transition_w - abs(x)) / transition_w :
            grip_w;

    // Cut the groove, extended past top and bottom faces
    translate([0, -plate_t / 2 - eps, 0])
        linear_extrude(height = plate_t + 2 * eps)
            polygon(points = [
                [-total_len / 2, groove_w(-total_len / 2) / 2],
                [ total_len / 2, groove_w( total_len / 2) / 2]
            ]);
}
