tick_count   = 24;    // number of radial tick marks
tick_w       = 1.2;   // tick width
tick_depth   = 1.5;   // tick depth from top face
tick_start_a = 0;     // angle of first tick (deg, +X axis)
eps          = 0.5;   // cutter overshoot past faces

$fn = 128;

// ---------- Model ----------
difference() {
    // Ring body
    cylinder(d = outer_d, h = thickness);

    // Central bore
    translate([0, 0, -eps])
        cylinder(d = inner_d, h = thickness + 2 * eps);

    // Radial tick grooves, cut into the top face
    for (i = [0 : tick_count - 1]) {
        a = tick_start_a + i * 360 / tick_count;
        translate([outer_d / 2, 0, thickness - tick_depth])
            rotate([0, 0, a])
                linear_extrude(height = tick_depth + eps, center = true)
                    polygon([[-tick_w / 2, -tick_w / 2],
                              [ tick_w / 2, -tick_w / 2],
                              [ tick_w / 2,  tick_w / 2],
                              [-tick_w / 2,  tick_w / 2]]);
    }
}
