// Powder measuring scoop
// Print orientation: bowl bottom on bed (z = 0), handle extending along +X

// ---------------- Parameters ----------------
bowl_radius      = 15;    // outer radius of spherical bowl (mm)
bowl_wall        = 1.5;   // thickness of bowl wall (mm)
handle_length    = 61.5;  // handle length from x = 13.5 to x = 75 (mm)
handle_width     = 8;     // handle width along Y (mm)
handle_thick     = 4;     // handle thickness along Z (mm)
cut_overlap      = 0.5;   // extra cut length past faces for clean differences (mm)
$fn              = 96;    // sphere resolution

// Derived values
inner_radius     = bowl_radius - bowl_wall;   // 13.5 mm
handle_x0        = bowl_radius - cut_overlap; // 14.5 mm (cut starts inside bowl)
handle_x1        = handle_length;             // 75 mm (cut ends at tip)
handle_z0        = bowl_radius - handle_thick; // 11 mm (handle bottom)
handle_z1        = bowl_radius;               // 15 mm (flush with rim)

// ---------------- Model ----------------
difference() {
    union() {
        // Lower half of hollow sphere: bowl + rim
        translate([0, 0, 0])
            sphere(r = bowl_radius);
        translate([0, 0, bowl_radius])
            sphere(r = inner_radius);
    }

    // Straight flat handle along +X, centred on y = 0
    translate([handle_x0, -handle_width / 2, handle_z0])
        cube([handle_x1 - handle_x0, handle_width, handle_thick]);

    // Cut the handle's path through the upper part of the bowl wall
    translate([handle_x0 - cut_overlap, -handle_width / 2, handle_z1])
        cube([(handle_x1 - handle_x0) + 2 * cut_overlap,
              handle_width,
              cut_overlap]);
}
