// Cable bridge for bench mat - 2 semicircular tunnels along Y at floor level
// Units: mm. Print orientation: base on bed (z = 0), builds upward.

$fn = 96;

// ---- Block ----
block_len   = 60;   // X length of block
block_wid   = 40;   // Y width of block
block_ht    = 20;   // Z height of block

// ---- Tunnels ----
tunnel_d    = 8;    // diameter of each semicircular tunnel (cylinder axis along Y)
tunnel_nx   = 20;   // spacing between tunnel axes along X
tunnel_z    = 0;    // tunnel axis height (floor level)

// ---- Cutting overlap ----
eps         = 0.5;  // extension past cut faces to avoid coplanar faces

difference() {
    // Main block, centred in X/Y, resting on z = 0
    translate([-block_len/2, -block_wid/2, 0])
        cube([block_len, block_wid, block_ht]);

    // Semicircular tunnels: cylinder axes along Y, centred along X
    for (i = [-1 : 1]) {
        translate([i * tunnel_nx/2, 0, tunnel_z])
            // cylinder along Z, upper half becomes a semicircular tunnel
            translate([0, 0, block_ht/2])
                rotate([90, 0, 0])
                    cylinder(d = tunnel_d, h = block_wid/2 + eps);
    }
}
