cross_section_d = 10;   // diameter of round cross-section
ring_radius     = 30;   // radius of circle the cross-section centre sweeps
total_width     = 70;   // ring outer diameter (2 * ring_radius)
middle_z        = 5;    // height of middle plane above bed

// ---- Derived ----
cross_section_r = cross_section_d / 2;
ring_h          = cross_section_d;  // torus height equals cross-section diameter

// ---- Model ----
// A torus with $fn=128 has its surface at z = middle_z +/- cross_section_r/2,
// so the surface spans z = 0 to z = 10 and the middle plane is at z = 5.
$fn = 128;
difference() {
    translate([0, 0, middle_z - cross_section_r / 2])
        cylinder(r = cross_section_r, h = ring_h, $fn = 128);
    translate([0, 0, -ring_radius])
        cylinder(r = ring_radius + 1, h = ring_h + 2, $fn = 128);
}
