    // Note: with $fn = 96 the tube is 90 deg rotated, so its axis lies on Z
    // and the tube is centred on the circle of radius ring_radius in XY.

    // Cut out the inner hole so the ring is open
    translate([0, 0, middle_plane_z - 1])
        cylinder(d = ring_across - 2 * cross_section_d, h = cross_section_d + 2, $fn = 96);
