plate_len   = 45;   // plate length along X
plate_wid   = 25;   // plate width along Y
plate_thk   = 2.5;  // plate thickness along Z

// ---- Knuckles ----
knuckle_d   = 7;    // knuckle diameter
knuckle_z   = 3.5;  // knuckle axis height above plate top
knuckle_n   = 3;    // number of segments (and knuckles, see below)
knuckle_x0  = 0;    // first segment start (will be centred)

// ---- Pin hole ----
pin_d       = 3;    // pin hole diameter

// ---- Misc ----
eps         = 0.5;  // cutter overshoot past faces

// Derived
seg_len = plate_len / knuckle_n;   // 15 mm each
// 1st and 3rd segments -> indices 0 and 2
knuckle_indices = [i for i in [0 : knuckle_n - 1] if i % 2 == 0];

difference() {
    union() {
        // Base plate, centred in X/Y, resting on z = 0
        translate([-plate_len / 2, -plate_wid / 2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckle cylinders, axis along X at y = 12.5
        for (i = knuckle_indices)
            translate([knuckle_x0 + i * seg_len - seg_len / 2,
                       plate_wid / 2,
                       knuckle_z])
                cylinder(d = knuckle_d, h = plate_thk + 2 * eps, $fn = 64);
    }

    // Pin hole along the knuckle axis through every knuckle
    for (i = knuckle_indices)
        translate([knuckle_x0 + i * seg_len - seg_len / 2,
                   plate_wid / 2,
                   knuckle_z - eps])
            cylinder(d = pin_d, h = plate_thk + 2 * eps, $fn = 64);
}
