gauge_length   = 40;   // gauge section length (X)
grip_width     = 15;   // grip section width (Y)
grip_length    = 35;   // grip section length (X)
transition_len = 15;   // transition section length (X)

// Derived
eps       = 0.5;   // cutter overshoot past faces
$fn       = 64;    // curve resolution (no curves here, set per rule)

// Check: 2*grip + gauge + 2*transition = 2*35 + 40 + 2*15 = 140 mm

// ---- Model ----
difference() {
    // Solid body: two grip blocks + gauge block + transition blocks
    union() {
        // Left grip
        translate([-total_length/2 + grip_length, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);

        // Right grip
        translate([total_length/2 - grip_length, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);

        // Gauge section (centred on origin)
        translate([-gauge_length/2, -gauge_width/2, 0])
            cube([gauge_length, gauge_width, thickness]);

        // Transition sections: width changes linearly from grip width to gauge width
        for (s = [-1, 1]) {   // s = -1 left, s = +1 right
            translate([s > 0 ? gauge_length/2 - transition_len : -total_length/2 + transition_len,
                       0,
                       0])
                cube([transition_len,
                      abs(s * (gauge_width - grip_width) / 2 + grip_width),
                      thickness]);
        }
    }

    // No holes needed for a plain tensile specimen
}
