    // Deburr / rounding notches at grip ends (optional, clean look)
    for (sx = [-1, 1])
        translate([sx * (gauge_x0 + gauge_length + transition_len / 2),
                   -grip_width / 2 - cut_extra, 0])
            cube([grip_length + cut_extra, grip_width + 2 * cut_extra, thickness]);
