        cylinder(d = inner_d, h = thickness + 2 * eps);

    // Radial tick grooves, first on +X axis
    for (i = [0 : tick_count - 1])
        rotate([0, 0, i * 360 / tick_count])
            translate([outer_d / 2 - tick_len, 0, thickness - tick_depth])
                cube([tick_w, tick_len + eps, tick_depth + eps]);
}
