// Anti-vibration foot for benchtop instrument
// Print orientation: flat bottom on bed (z = 0), builds upward (+Z)

// ---------- Parameters ----------
foot_d_bottom   = 40;    // frustum diameter at bottom (z = 0)
foot_d_top      = 30;    // frustum diameter at top (z = 12)
foot_height     = 12;    // frustum height (top is at z = 12)

pad_d           = 34;    // recess diameter for rubber pad
pad_depth       = 2;     // recess depth from bottom face

screw_d         = 5.5;   // through-hole diameter for screw
screw_position  = [0, 0]; // screw hole centre (X, Y)

eps             = 0.5;   // cutter overshoot past faces
$fn             = 128;   // curve resolution

// ---------- Model ----------
difference() {
    // Frustum body, centred on Z axis
    translate([0, 0, 0])
        cylinder(d1 = foot_d_bottom, d2 = foot_d_top, h = foot_height);

    // Round recess for rubber pad, cut into bottom face
    translate([0, 0, -eps])
        cylinder(d = pad_d, h = pad_depth + 2 * eps);

    // Central screw through-hole along the axis
    translate(screw_position)
        cylinder(d = screw_d, h = foot_height + 2 * eps, center = true);
}
