// Stiffened cover panel
// Print orientation: plate flat on bed, ribs pointing up (+Z)

// ---------- Parameters ----------
plate_len   = 80;   // plate length along X (mm)
plate_wid   = 80;   // plate width along Y (mm)
plate_thk   = 2;    // plate thickness (mm), z = 0..2

rib_h       = 4;    // rib height above plate (mm), z = 2..6
rib_thk     = 2;    // rib thickness along X (mm)
rib_count   = 3;    // number of ribs
rib_pitch   = 20;   // centre-to-centre spacing of ribs (mm)

eps         = 0.5;  // overlap/merge tolerance (mm)
$fn         = 64;   // curve resolution (no curves here, set per convention)

// ---------- Derived ----------
// Ribs run the full width along Y, centred on the plate
rib_wid = plate_wid;  
// Check: 4 equal parts -> outer rib centres 20 mm from ends
assert(abs(rib_pitch * (rib_count - 1) / 2 - (plate_len - 2 * rib_thk) / 2) < 0.001,
       "rib_pitch does not place outer ribs 20 mm from the ends");

// ---------- Model ----------
union() {
    // Base plate
    translate([-plate_len / 2, -plate_wid / 2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs, standing on the plate (slight overlap into plate for a clean union)
    for (i = [0 : rib_count - 1]) {
        x = -plate_len / 2 + rib_thk / 2 + i * rib_pitch;
        translate([x, -rib_wid / 2, plate_thk - eps])
            cube([rib_thk, rib_wid, rib_h + eps]);
    }
}
