rib_x2 = plate_len/2 - rib_offset;    // last rib centre (right)

// ---------------- Model ----------------
union() {
    // Base plate, centred in X and Y, resting on z = 0
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs running full width along Y, standing on the plate
    // (overlap into plate by eps so the union is one solid)
    for (i = [0 : rib_count - 1]) {
        translate([rib_x0 + i * rib_pitch - rib_thk/2,
                   -plate_wid/2,
                   plate_thk - eps])
            cube([rib_thk, plate_wid, rib_h + eps]);
