// Ring weight for a flask neck in a water bath
// Print orientation: flat on the bed, middle plane at z = 8

// ---- Dimensions (mm) ----
cross_section_d      = 16;   // diameter of the round cross-section
ring_radius          = 30;   // radius of the circle the cross-section centre sweeps
ring_width           = 76;   // overall across dimension (2 * ring_radius)
middle_plane_z       = 8;    // z of the torus middle plane
bottom_face_z        = 0;    // z where the part rests on the bed

// ---- Derived ----
cross_section_r      = cross_section_d / 2;
tube_r               = cross_section_r;   // tube radius = cross-section radius
cut_extra            = 0.5;              // overshoot for clean cuts

$fn = 128;  // smoothness of curved surfaces

// ---- Model ----
// A torus is defined by a tube radius and a distance from the tube axis to the
// origin. Here the tube axis is the Z axis, and the distance is ring_radius.
// The result spans z = middle_plane_z - tube_r to z = middle_plane_z + tube_r,
// which places the bottom face exactly on z = 0.
difference() {
    translate([0, 0, middle_plane_z - tube_r])
        torus(r = ring_radius, h = tube_r * 2);

    // Optional: a small central core along Z, so the ring is hollow through the middle
    translate([0, 0, middle_plane_z - tube_r - cut_extra])
        cylinder(r = ring_radius - tube_r - 1, h = tube_r * 2 + 2 * cut_extra);
}
```

