// Leaf of a pin hinge
// Print orientation: flat on bed, knuckles pointing up (+Z)

$fn = 64;

// ---- Plate ----
plate_len   = 40;   // plate length along X
plate_wid   = 30;   // plate width along Y
plate_thk   = 2.5;  // plate thickness along Z

// ---- Knuckles ----
knuckle_d   = 6;    // knuckle diameter
knuckle_n   = 5;    // number of segments (and knuckles)
knuckle_x0  = 0;    // first segment start (X)
knuckle_y   = 15;   // knuckle axis Y position (on +Y edge)
knuckle_z   = 3;    // knuckle axis height above plate

// ---- Pin hole ----
pin_d       = 2.5;  // pin hole diameter

// ---- Misc ----
eps         = 0.5;  // cutter overshoot past faces

// Segment length along X
seg_len = plate_len / knuckle_n;

// Which segments carry knuckles (1st, 3rd, 5th)
knuckle_indices = [i for i in [0 : knuckle_n - 1] if (i + 1) % 2 == 1];

difference() {
    // Base plate, centred in X/Y, resting on z = 0
    translate([-plate_len / 2, -plate_wid / 2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Knuckles along X, each with a pin hole through the axis
    for (idx = knuckle_indices) {
        translate([knuckle_x0 + idx * seg_len - seg_len / 2,
                   knuckle_y,
                   knuckle_z])
            difference() {
                cylinder(d = knuckle_d, h = plate_thk + 2 * eps);
                translate([0, 0, -eps])
                    cylinder(d = pin_d, h = plate_thk + 2 * eps);
            }
    }
}
