        for (s = knuckle_sel)
            translate([(s - 1) * seg_len - (knuckle_n + 1) * seg_len / 2,
                       plate_wid/2,
                       knuckle_z])
                cylinder(d = knuckle_d, h = plate_thk + 2 * eps);
