    // Pin holes through every knuckle along the X axis
    for (s = knuckle_sel)
        translate([(s - 1) * seg_len - (knuckle_n + 1) * seg_len / 2,
                   plate_wid/2,
                   knuckle_z])
            translate([-plate_len/2 - eps, 0, 0])
