seg_len = plate_len / knuckle_n;

// Segment centres along X
function seg_c(i) = knuckle_x0 + (i + 0.5) * seg_len;

// Knuckle centres (only odd segments: 1st, 3rd, 5th)
function knuckle_c(i) = seg_c(2 * i);   // i = 0..2 -> X = 4, 12, 20

difference() {
    // Base plate, centred in X/Y, resting on z = 0
    translate([-plate_len / 2, -plate_wid / 2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Knuckles with pin holes
    for (i = [0 : 2]) {
        translate([knuckle_c(i), knuckle_y, knuckle_z])
            difference() {
                cylinder(d = knuckle_d, h = plate_thk + 2 * eps);
                translate([0, 0, -eps])
                    cylinder(d = pin_d, h = plate_thk + 2 * eps);
            }
    }
