// Leaf of a pin hinge
// Print orientation: flat plate on the bed, knuckles pointing up (+Z)

// ---------- Parameters ----------
plate_len   = 40;    // plate length along X (mm)
plate_wid   = 25;    // plate width along Y (mm)
plate_thk   = 2.5;   // plate thickness along Z (mm)

knuckle_d   = 8;     // knuckle cylinder diameter (mm)
knuckle_z   = 4;     // height of knuckle top above plate (mm)
knuckle_n   = 5;     // number of segments along the edge
knuckle_sel = [1, 3, 5]; // 1-based segment numbers that get knuckles

pin_d       = 2;     // pin hole diameter (mm)

eps         = 0.5;   // cutter overshoot past faces (mm)
$fn         = 96;    // curve resolution

// ---------- Derived ----------
seg_len = plate_len / knuckle_n;   // 8 mm segment length
r_k     = knuckle_d / 2;           // knuckle radius
r_p     = pin_d / 2;               // pin hole radius

// ---------- Model ----------
difference() {
    union() {
        // Base plate, centred in X/Y, resting on z = 0
        translate([-plate_len / 2, -plate_wid / 2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles along +Y edge (y = plate_wid / 2), axis at z = knuckle_z
        for (s = knuckle_sel)
            translate([s * seg_len - seg_len / 2, plate_wid / 2, knuckle_z])
                cylinder(r = r_k, h = knuckle_thk + plate_thk, $fn = $fn);
    }

    // Pin holes running along the knuckle axis through every knuckle
    for (s = knuckle_sel)
        translate([s * seg_len - seg_len / 2, plate_wid / 2, knuckle_z])
            translate([0, 0, -eps])
                cylinder(r = r_p, h = knuckle_thk + plate_thk + 2 * eps, $fn = $fn);
}
