// Star-shaped indexing wheel
// Print orientation: flat on bed, z = 0 up to plate thickness

// ---------------- Parameters ----------------
plate_thickness   = 5;     // plate thickness (Z)
outer_radius      = 35;    // distance of outer points from centre
inner_radius      = 17.5;  // distance of inner points from centre
hole_radius       = 3;     // central through-hole radius (6 mm diameter)
point_count       = 6;     // number of star points
cut_extra         = 0.5;   // overshoot for clean boolean cuts
$fn               = 96;    // curve resolution

// ---------------- Model ----------------
difference() {
    // Star outline, centred in XY, first outer point on +X axis
    hull() {
        for (i = [0 : point_count - 1]) {
            rotate(i * 360 / point_count)
                translate([outer_radius, 0, 0])
                    cylinder(h = plate_thickness, $fn = 16);
            rotate(i * 360 / point_count + 180 / point_count)
                translate([inner_radius, 0, 0])
                    cylinder(h = plate_thickness, $fn = 16);
        }
    }

    // Central through-hole, extends past top and bottom faces
    translate([0, 0, -cut_extra])
        cylinder(h = plate_thickness + 2 * cut_extra, r = hole_radius, $fn = 64);
}
