// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 upward

// ---- Dimensions (mm) ----
thickness      = 4;    // specimen thickness (Z)
total_length   = 130;  // overall length along X
gauge_width    = 6;    // gauge section width (Y)
gauge_length   = 50;   // gauge section length (X)
grip_width     = 19;   // grip section width (Y)
grip_length    = 25;   // grip section length (X)
transition_len = 15;   // transition section length (X)

// ---- Derived ----
transition_start = -total_length/2 + grip_length + transition_len;  // -60
transition_end   = total_length/2 - grip_length - transition_len;   // 60

$fn = 64;

difference() {
    // Main body
    union() {
        // Left grip
        translate([-total_length/2, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);
        // Right grip
        translate([total_length/2 - grip_length, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);
        // Gauge
        translate([transition_end, -gauge_width/2, 0])
            cube([gauge_length, gauge_width, thickness]);
        // Transitions
        for (s = [-1, 1]) {
            translate([s * transition_start, 0, 0])
                rotate([0, 90, 0])
                    linear_extrude(thickness)
                        polygon(points = [
                            [s > 0 ? transition_start : transition_end, -grip_width/2],
                            [s > 0 ? transition_start : transition_end, grip_width/2],
                            [s * (transition_start + (transition_end - transition_start)/2), -gauge_width/2],
                            [s * (transition_start + (transition_end - transition_start)/2), gauge_width/2]
                        ]);
        }
    }
}
