$fn       = 64;                        // curve resolution (no curves here, set per convention)
gauge_x0  = -(total_length / 2) + grip_length + transition_len;  // gauge start X
gauge_x1  = gauge_x0 + gauge_length;   // gauge end X

// ---- Model ----
difference() {
    // Main body
    translate([-total_length / 2, -grip_width / 2, 0])
        linear_extrude(thickness)
            polygon([
                [-total_length / 2, -grip_width / 2],
                [ total_length / 2, -grip_width / 2],
                [ total_length / 2,  grip_width / 2],
                [-total_length / 2,  grip_width / 2]
            ]);

    // Gauge section (narrow middle)
    translate([gauge_x0, -gauge_width / 2, 0])
        linear_extrude(thickness)
            polygon([
                [gauge_x0, -gauge_width / 2],
                [gauge_x1, -gauge_width / 2],
                [gauge_x1,  gauge_width / 2],
                [gauge_x0,  gauge_width / 2]
            ]);

    // Transition sections (width 20 -> 8, then 8 -> 20)
    for (s = [-1, 1]) {
        translate([s * (gauge_x0 + gauge_length / 2) - transition_len,
                   -grip_width / 2, 0])
            linear_extrude(thickness)
                polygon([
                    [s * (gauge_x0 + gauge_length / 2) - transition_len, -grip_width / 2],
                    [gauge_x0 + s * gauge_length / 2,                    -grip_width * 0.9], // 18 mm
                    [gauge_x0 + s * gauge_length / 2,                    gauge_width / 2],
                    [s * (gauge_x0 + gauge_length / 2) - transition_len, gauge_width / 2]
