// ---- Model ----
difference() {
    // Plate body
    translate([-model_len/2, -plate_t/2, 0])
        cube([model_len, plate_t, plate_t]);

    // Grip cutouts (leaving grip sections at each end)
    for (s = [-1, 1]) {
        x0 = -model_len/2 + grip_len;            // start of first transition
        x1 = -model_len/2 + grip_len + transition_w; // end of first transition
        translate([s * x0, -plate_t/2 - eps, 0])
            rotate([90, 0, 0])
                linear_extrude(height = plate_t + 2*eps)
                    polygon([
                        [0, -grip_w/2],
                        [x1 - x0, -grip_w/2],
                        [x1 - x0, grip_w/2],
                        [0, grip_w/2]
                    ]);
    }
