tick_count   = 12;    // number of radial tick marks
tick_w       = 1;     // tick groove width
tick_depth   = 1.5;   // tick groove depth from top face
tick_len     = 3;     // tick groove length inward from outer edge
cut_extra    = 0.5;   // overshoot of cutters past faces
$fn          = 128;   // curve resolution

// ---------- Derived ----------
tick_r_start = outer_d / 2 - tick_len;   // groove starts this radius
tick_r_end   = outer_d / 2 + cut_extra;  // groove ends this radius (over outer edge)

// ---------- Model ----------
difference() {
    // Ring body
    cylinder(d = outer_d, h = thickness);

    // Central bore
    translate([0, 0, -cut_extra])
        cylinder(d = inner_d, h = thickness + 2 * cut_extra);

    // Radial tick grooves, first on +X axis
    for (i = [0 : tick_count - 1])
        rotate([0, 0, i * 360 / tick_count])
            translate([tick_r_start, 0, thickness - tick_depth])
                cube([tick_len + cut_extra, tick_w, tick_depth + cut_extra]);
}
