// Stiffened cover panel
// Print orientation: plate flat on bed, ribs pointing up (+Z)

// ---------- Parameters ----------
plate_len   = 80;    // plate length along X (mm)
plate_wid   = 80;    // plate width along Y (mm)
plate_thk   = 2;     // plate thickness (mm), z = 0..2

rib_h       = 4;     // rib height above plate (mm), z = 2..6
rib_thk     = 2;     // rib thickness along X (mm)
rib_count   = 4;     // number of ribs
rib_pitch   = 16;    // centre-to-centre spacing along X (mm)

eps         = 0.5;   // overlap for clean unions (mm)
$fn         = 64;    // curve resolution

// ---------- Derived ----------
rib_x0 = -plate_len/2 + rib_pitch/2 + rib_thk/2;   // first rib centre X
// (outer ribs at 16 mm from ends: -40 + 16 = -24, +40 - 16 = +24)

// ---------- Model ----------
union() {
    // Base plate
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs, running full width along Y
    for (i = [0 : rib_count - 1]) {
        translate([rib_x0 + i * rib_pitch - rib_thk/2,
                   -plate_wid/2 - eps,
                   plate_thk])
            cube([rib_thk, plate_wid + 2*eps, rib_h]);
    }
}
