wall          = 1.5;   // bowl wall thickness
bowl_z        = sphere_r; // centre height (lower half kept, rim at z = 10)

// ---- Handle ----
handle_w      = 10;    // handle width (Y)
handle_t      = 3;     // handle thickness (Z)
handle_x0     = 8.5;   // handle start (X)
handle_x1     = 90;    // handle end (X)
handle_top_z  = bowl_z - handle_t; // top face flush with rim (z = 7)

// ---- Cut clearance ----
eps           = 0.5;   // extension of cutting shapes past faces

difference() {
    union() {
        // Hollow spherical bowl (lower half)
        translate([0, 0, bowl_z])
            sphere(r = sphere_r);
        translate([0, 0, 0])
            sphere(r = sphere_r - wall);

        // Flat handle along +X
        translate([handle_x0, -handle_w / 2, 0])
            cube([handle_x1 - handle_x0, handle_w, handle_t]);
    }

    // Through-hole along +X, starting before the bowl and running through
    // the handle (keeps the bore round and the same length)
    translate([handle_x0 - eps, 0, handle_top_z])
        rotate([0, 90, 0])
            cylinder(h = handle_x1 - handle_x0 + 2 * eps, r = 4);
}
