        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on 1st, 3rd, 5th segments
        for (i = [0 : 2 : knuckle_n - 1]) {
            x = knuckle_x0 + (i + 0.5) * plate_len / knuckle_n;
            translate([x, knuckle_y, knuckle_z])
                cylinder(d = knuckle_d, h = plate_thk + 2 * eps, center = true);
        }
    }

    // Pin holes through every knuckle
    for (i = [0 : 2 : knuckle_n - 1]) {
        x = knuckle_x0 + (i + 0.5) * plate_len / knuckle_n;
        translate([x, knuckle_y, knuckle_z])
            cylinder(d = pin_d, h = plate_thk + 2 * eps, center = true);
