plate_wid      = 30;    // plate width along Y (mm)
plate_thk      = 2.5;   // plate thickness along Z (mm)

knuckle_count  = 5;     // number of segments (and knuckles on odd segments)
knuckle_d      = 6;     // knuckle cylinder diameter (mm)
knuckle_h      = 6;     // knuckle height above plate top (mm)
knuckle_x      = 12;    // spacing between segment centres (mm)

