$fn            = 96;    // curve resolution

// ---------- Derived ----------
knuckle_z      = plate_thk + knuckle_h;   // axis height of knuckles
odd_segments   = [i for i in [0 : knuckle_count - 1] if i % 2 == 0]; // 1st,3rd,5th

// ---------- Model ----------
union() {
    // Base plate, centred in X/Y, resting on z = 0
    translate([-plate_len / 2, -plate_wid / 2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Knuckles along +Y edge (y = 15), axis along X
    for (s = odd_segments)
        translate([s * knuckle_x - knuckle_x / 2, plate_wid / 2, 0])
            difference() {
                cylinder(d = knuckle_d, h = knuckle_h, $fn = 64);
                // Pin hole through the knuckle
                translate([0, 0, -eps])
                    cylinder(d = pin_d, h = knuckle_h + 2 * eps, $fn = 64);
