// Leaf of a pin hinge
// Print orientation: flat on bed, knuckles pointing up (+Z)

$fn = 64;

// ---- Plate ----
plate_len   = 60;    // plate length along X
plate_wid   = 30;    // plate width along Y
plate_thk   = 2.5;   // plate thickness along Z

// ---- Knuckles ----
knuckle_d   = 6;     // knuckle diameter
knuckle_z   = 3;     // knuckle axis height above plate
knuckle_n   = 5;     // number of segments along length
knuckle_pitch = plate_len / knuckle_n; // 12 mm spacing

// ---- Pin hole ----
pin_d       = 3;     // pin hole diameter

// ---- Misc ----
eps         = 0.5;   // cutter overshoot past faces

difference() {
    // Base plate, centred in X/Y, resting on z = 0
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Knuckles on 1st, 3rd, 5th segments (odd indices)
    for (i = [0 : knuckle_n - 1]) {
        if ((i + 1) % 2 == 0) continue;
        x = (i - (knuckle_n - 1)/2) * knuckle_pitch;
        translate([x, plate_wid/2, 0]) {
