                   plate_width / 2, 0])
            difference() {
                cylinder(d = knuckle_dia, h = knuckle_h + eps, $fn = 96);
                // Pin hole through the knuckle (extends past top face)
                translate([0, 0, knuckle_z - eps])
                    cylinder(d = pin_dia, h = knuckle_h + 2 * eps, $fn = 96);
