```openscad
// Star-shaped indexing wheel
// Print orientation: flat on bed, z = 0 up to plate thickness

// ---------------- Parameters ----------------
plate_thickness   = 5;     // plate thickness (Z)
outer_radius      = 40;    // distance of outer points from centre
inner_radius      = 24;    // distance of inner points from centre
hole_radius       = 8;     // central through-hole radius
point_count       = 8;     // number of star points (even)
cut_extra         = 0.5;   // overshoot for clean boolean cuts
$fn               = 96;    // curve resolution

// ---------------- Model ----------------
difference() {
    // 8-pointed star outline, first outer point on +X axis
    star_outline = concat(
        [for (i = [0 : point_count / 2 - 1])
            each [
                [outer_radius * cos((2 * i) * 180 / point_count),
                 outer_radius * sin((2 * i) * 180 / point_count)],
                [inner_radius * cos(((2 * i + 1) * 180 / point_count) - 90),
                 inner_radius * sin(((2 * i + 1) * 180 / point_count) - 90)]
            ]],
        [for (i = [0 : point_count / 2 - 1])
            each [
                [inner_radius * cos(((2 * i + 1) * 180 / point_count) + 90),
                 inner_radius * sin(((2 * i + 1) * 180 / point_count) + 90)],
                [outer_radius * cos((2 * i + 2) * 180 / point_count),
                 outer_radius * sin((2 * i + 2) * 180 / point_count)]]
            ]);

    // Plate body
    linear_extrude(height = plate_thickness)
        polygon(points = star_outline);

    // Central through-hole
    translate([0, 0, -cut_extra])
        cylinder(r = hole_radius, h = plate_thickness + 2 * cut_extra);
}
```

