// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 up to z = thickness

// ---------------- Parameters ----------------
thickness      = 3;     // specimen thickness (Z)
total_length   = 120;   // overall length along X (mm)
gauge_width    = 6;     // gauge section width (Y)
gauge_length   = 30;    // gauge section length (X)
grip_width     = 15;    // grip section width (Y)
grip_length    = 35;    // grip section length (X)
transition_len = 10;    // transition section length (X)
cut_extra      = 0.5;   // overshoot for clean boolean cuts (mm)
$fn            = 64;    // curve resolution

// Derived
grip_x0 = -(total_length / 2) + grip_length;   // grip start (X)
gauge_x0 = grip_x0 + grip_length + transition_len; // gauge start (X)

// ---------------- Model ----------------
difference() {
    // Main body: grip -> transition -> gauge -> transition -> grip
    union() {
        // Left grip
        translate([grip_x0 - grip_length, -grip_width / 2, 0])
            cube([grip_length, grip_width, thickness]);

        // Left transition (15 -> 6 mm width)
        translate([gauge_x0 - transition_len, -grip_width / 2, 0])
            linear_extrude(thickness)
                polygon(points = [
                    [gauge_x0 - transition_len, -grip_width / 2],
                    [gauge_x0 - transition_len,  grip_width / 2],
                    [gauge_x0,                 gauge_width / 2],
                    [gauge_x0,                 -gauge_width / 2]
                ]);

        // Gauge section
        translate([gauge_x0, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, thickness]);

        // Right transition (6 -> 15 mm width)
        translate([gauge_x0 + gauge_length, -gauge_width / 2, 0])
            linear_extrude(thickness)
                polygon(points = [
                    [gauge_x0 + gauge_length, -gauge_width / 2],
                    [gauge_x0 + gauge_length,  gauge_width / 2],
                    [gauge_x0 + transition_len,  grip_width / 2],
                    [gauge_x0 + transition_len, -grip_width / 2]
                ]);

        // Right grip
        translate([gauge_x0 + gauge_length + transition_len, -grip_width / 2, 0])
            cube([grip_length, grip_width, thickness]);
    }

