// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 up to plate_t

$fn = 64;

// ---- Dimensions (mm) ----
plate_t      = 3;     // plate thickness (Z)
gauge_w      = 8;     // gauge section width (Y)
gauge_l      = 50;    // gauge section length (X)
grip_w       = 20;    // grip section width (Y)
grip_l       = 30;    // grip section length (X)
transition_l = 10;    // transition section length (X)
total_l      = 130;   // overall length (X)

// ---- Derived ----
eps       = 0.01;                    // cutter overshoot
join      = min(transition_l/2, 1);  // overlap for hull (safety)

// Check: 2*grip_l + gauge_l + 2*transition_l = 130
assert(abs(2*grip_l + gauge_l + 2*transition_l - total_l) < 0.001, "length mismatch");

// ---- Model ----
difference() {
    union() {
        // Grip sections
        translate([-total_l/2 + grip_l, -grip_w/2, 0])
            cube([grip_l, grip_w, plate_t]);
        translate[total_l/2 - grip_l, -grip_w/2, 0]
            cube([grip_l, grip_w, plate_t]);

        // Gauge section
        translate([-gauge_l/2, -gauge_w/2, 0])
            cube([gauge_l, gauge_w, plate_t]);

        // Transitions (width changes linearly from grip to gauge)
        for (s = [-1, 1]) {
            x0 = -total_l/2 + join;              // start in grip
            w0 = grip_w - 2*join*(grip_w - gauge_w)/transition_l;  // w = 20 at x0
            hull() {
                translate([x0, -w0/2, 0])
                    cube([join, w0, plate_t]);
                translate([-s*(total_l/2 - gauge_l/2 - join), -gauge_w/2, 0])
                    cube([s*(total_l/2 - gauge_l/2 - join) + join, gauge_w, plate_t]);
            }
        }
    }

    // Deburr / round edges along Z
    for (dx = [-1, 1])
        for (dy = [-1, 1])
            translate([dx * (total_l/2 - 1), dy * (plate_t/2 - 1), 0])
                cube([2, plate_t, 2]);
}
