outer_diameter   = 80;    // outer rim outer diameter
rim_width        = 5;     // rim width (radial)
hub_diameter     = 14;    // central hub diameter
axle_hole_d      = 8;     // axle hole diameter through hub
spoke_count      = 5;     // number of spokes
spoke_width      = 5;     // spoke width (radial)
cut_extra        = 0.5;   // overshoot for clean boolean cuts
$fn              = 128;   // curve resolution

// ---------- Derived ----------
rim_id = outer_diameter - 2 * rim_width;   // rim inner diameter
spoke_start_r = hub_diameter / 2 - cut_extra; // spoke inner radius (into hub)
spoke_end_r   = outer_diameter / 2 - cut_extra; // spoke outer radius (into rim)

// ---------- Model ----------
difference() {
    union() {
        // Outer rim
        cylinder(d = outer_diameter, h = part_thickness);

        // Central hub with axle hole
        translate([0, 0, -cut_extra])
            cylinder(d = hub_diameter, h = part_thickness + 2 * cut_extra);
        translate([0, 0, -cut_extra])
            cylinder(d = axle_hole_d, h = part_thickness + 2 * cut_extra);

        // Radial spokes, first along +X axis
        for (i = [0 : spoke_count - 1])
            rotate([0, 0, i * 360 / spoke_count])
                translate([spoke_start_r, 0, -cut_extra])
                    cube([spoke_end_r - spoke_start_r,
                          spoke_width,
                          part_thickness + 2 * cut_extra]);
    }

    // Clean up overlapping rim/spoke regions (small overlap avoids coplanar faces)
    for (i = [0 : spoke_count - 1])
        rotate([0, 0, i * 360 / spoke_count])
            translate([spoke_end_r - 0.5, -spoke_width / 2 - 0.5, 0])
                cube([spoke_width + 1, spoke_width + 1, part_thickness]);
}
