// Ring weight for a flask neck in a water bath
// Print orientation: flat on the bed, middle plane at z = 4

// ---- Dimensions (mm) ----
cross_section_d      = 8;     // diameter of the round cross-section
ring_radius          = 28;    // radius of the circle the cross-section centre traces
ring_across          = 64;    // overall diameter of the ring (2 * ring_radius)
middle_plane_z       = 4;     // height of the ring's middle plane
cut_extra            = 0.5;   // overshoot for any cutting shapes

$fn = 96;                     // smoothness of curved surfaces

// ---- Derived ----
cross_section_r = cross_section_d / 2;   // 4 mm
ring_inner_r    = ring_radius - cross_section_r;  // 24 mm
ring_outer_r    = ring_radius + cross_section_r;  // 32 mm
ring_h          = cross_section_d;         // 8 mm (thick torus)

// ---- Model ----
difference() {
    // Solid torus, centred on the origin, middle plane at z = 0
    translate([0, 0, middle_plane_z])
        cylinder(r = ring_outer_r, h = ring_h, $fn = 96);

    // Central cavity along Z, extending past both top and bottom faces
    translate([0, 0, middle_plane_z - cut_extra])
        cylinder(r = ring_inner_r, h = ring_h + 2 * cut_extra, $fn = 96);
}
