        translate([-segment_w/2 + (i + 1) * segment_w/2,
                   plate_wid/2 - eps,
                   plate_thk])
            translate([0, 0, -eps])
                cylinder(d = pin_d, h = knuckle_h + 2*eps, $fn = 96);
