// ---------------- Parameters ----------------
disc_d      = 50;    // cam disc diameter
disc_h      = 8;     // cam disc thickness
offset_x    = 5;     // disc centre X offset from shaft axis
offset_y    = 0;     // disc centre Y offset from shaft axis

hub_d       = 12;    // shaft hub diameter
hub_h       = 6;     // shaft hub height above disc (z = 8 to 14)

shaft_d     = 6;     // shaft hole diameter
shaft_len   = 1;     // shaft hole overcut past faces

eps         = 0.5;   // cutter overshoot for clean differences

$fn = 128;           // smoothness of curved surfaces

// ---------------- Model ----------------
difference() {
    union() {
        // Cam disc, centred at (offset_x, offset_y, 0)
        translate([offset_x, offset_y, 0])
            cylinder(d = disc_d, h = disc_h);

        // Shaft hub, centred on the Z axis, spanning z = 8 to 14
        translate([0, 0, disc_h + hub_h - 0.01])
            cylinder(d = hub_d, h = hub_h + 0.01);
    }

    // Shaft hole: starts above the disc, runs through the hub,
    // and extends len past the top face (z = 14 + len)
    translate([0, 0, disc_h + hub_h - eps])
        cylinder(d = shaft_d, h = hub_h + eps + shaft_len);
}
