// Print orientation: flat on bed, z = 0 up to plate_t

// ---- Parameters ----
outer_r   = 30;   // distance of outer points from centre
inner_r   = 15;   // distance of inner points from centre
points    = 5;    // number of star points
plate_t   = 3;    // plate thickness
hole_d    = 6;    // central through-hole diameter
eps       = 0.5;  // cutter overshoot past faces

$fn = 96;

// ---- Model ----
difference() {
    // Star outline, first outer point on +X axis
    hull() {
        for (i = [0 : points - 1])
            rotate([0, 0, i * 360 / points])
                translate([outer_r, 0, 0])
                    cylinder(h = plate_t, $fn = 16);
    }

    // Central hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = plate_t + 2 * eps, $fn = 64);
}
```

