// Width at a given X position (linear profile)
function width_at(x) =
    if (x < -grip_length)
        grip_width;
    else if (x < -grip_length + transition_len)
        grip_width + (10 - grip_width) * (x + grip_length - transition_len) / transition_len;
    else if (x < -grip_length + 2*transition_len)
        gauge_width;
    else if (x < grip_length - 2*transition_len)
        gauge_width;
    else if (x < grip_length - transition_len)
        gauge_width + (grip_width - gauge_width) * (x - grip_length + transition_len) / transition_len;
    else
        grip_width;

