// ---- Derived ----
transition_start = -total_length/2 + grip_length;   // -62.5
transition_end   = transition_start + transition_len; // -47.5

// ---- Model ----
difference() {
    union() {
        // Grip sections
        translate([-total_length/2, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);
        translate([total_length/2 - grip_length, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);

        // Gauge section
        translate([0, -gauge_width/2, 0])
            cube([gauge_length, gauge_width, thickness]);

        // Transition sections (width changes linearly from grip to gauge)
        for (s = [-1, 1]) {
            translate([s * (total_length/2 - grip_length - transition_len), -gauge_width/2, 0])
                linear_extrude(thickness)
                    polygon(points = [
                        [s * (total_length/2 - grip_length - transition_len), -gauge_width/2],
                        [s * (total_length/2 - grip_length - transition_len + transition_len), -gauge_width/2],
                        [s * (total_length/2 - grip_length - transition_len + transition_len), gauge_width/2],
                        [s * (total_length/2 - grip_length - transition_len), gauge_width/2]
                    ]);
        }
    }
    // No holes needed for a solid tensile bar
}
