grip_width     = 20;    // grip section width (Y)
grip_length    = 35;    // grip section length (X)
transition_len = 15;    // transition section length (X)
cut_overlap    = 0.5;   // extra length on cutters to avoid coplanar faces

$fn = 64;

// Derived
witness = grip_width + 2 * transition_len + gauge_width;  // check width

// ---------------- Model ----------------
difference() {
    union() {
        // End grips
        translate([-total_length / 2 + grip_length, -grip_width / 2, 0])
            cube([grip_length, grip_width, thickness]);
        translate([total_length / 2 - grip_length, -grip_width / 2, 0])
            cube([grip_length, grip_width, thickness]);

        // Gauge section
        translate([-gauge_length / 2, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, thickness]);

        // Transitions (2D width drawn along Y, extruded)
        for (s = [-1, 1])
            translate([s > 0 ? gauge_length / 2 - transition_len : -gauge_length / 2,
                       0, 0])
                rotate([90, 0, 0])
                    linear_extrude(thickness)
                        polygon([
                            [s > 0 ? gauge_length / 2 - transition_len,
                             s * (gauge_width - grip_width) / 2],
                            [s > 0 ? gauge_length / 2,
                             s * (gauge_width - grip_width) / 2],
                            [s > 0 ? gauge_length / 2,
                             -s * (gauge_width - grip_width) / 2],
                            [s > 0 ? gauge_length / 2 - transition_len,
                             -s * (gauge_width - grip_width) / 2]
                        ]);
    }

    // Deburring cuts
    for (x = [-total_length / 2 + grip_length + cut_overlap,
               total_length / 2 - grip_length - cut_overlap])
        translate([x, -grip_width / 2 - cut_overlap, 0])
            cube([cut_overlap, grip_width + 2 * cut_overlap, thickness]);
}
